  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Artemisinin, a sesquiterpene lactone natural product, shows low oral bioavailability in healthy volunteers and malaria patients, supporting low F for the query's polycyclic lactone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Limonin, a polycyclic triterpenoid lactone, exhibits poor oral bioavailability in humans, analogous to the query's multiple lactone rings.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "EM574, a macrocyclic lactone, has very low oral bioavailability (~2%) in humans due to extensive first-pass metabolism, supporting low F for lactone-containing natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Fluticasone, a lipophilic steroid-like lactone, has negligible (<1%) oral bioavailability via gastrointestinal absorption, indicating that complex lipophilic lactones can have very low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Clarithromycin, a macrolide lactone, has ~55% oral bioavailability, providing a contradictory example that some lactone-containing natural products are well absorbed, though it is structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a complex polycyclic lactone natural product with multiple lactone rings and a tert-butyl group. The most transferable analogues (artemisinin, limonin, EM574, fluticasone) consistently show low or very low oral bioavailability due to poor solubility, first-pass metabolism, or efflux. Although some macrolide and corticosteroid analogues have high F, they are structurally distant and less transferable. Therefore, the query is predicted to have F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "All retrieved evidence molecules have low Morgan similarity (<0.2), limiting transferability.",
    "The query's exact physicochemical properties (solubility, permeability, transporter liability) are not provided."
  ],
